function parseMoney(raw) {
  if (typeof raw === 'number') return Number.isFinite(raw) && raw >= 0 ? raw : 0;
  const s = String(raw ?? '').trim().replace(/[€$£\s\u00A0]/g, '').replace(/^CHF/i, '');
  if (!s) return 0;
  let normalized = s;
  if (/^\d{1,3}(\.\d{3})+(,\d+)?$/.test(s)) {
    normalized = s.replace(/\./g, '').replace(',', '.');
  } else if (/^\d{1,3}(,\d{3})+(\.\d+)?$/.test(s)) {
    normalized = s.replace(/,/g, '');
  } else {
    normalized = s.replace(',', '.');
  }
  const n = Number(normalized);
  return Number.isFinite(n) && n >= 0 ? n : 0;
}

const inputItems = $input.all();
const output = [];

for (const item of inputItems) {
  const d = item.json || {};
  const rawQuery = String(
    d['Vendor Identifier or Legal Name'] ?? d.query ?? d.vatNumber ?? d.vendorName ?? ''
  ).trim();
  const rawCountry = String(
    d['Country (ISO-2, optional)'] ?? d.defaultCountry ?? d.country ?? ''
  ).trim().toUpperCase().replace(/[^A-Z]/g, '').slice(0, 2);
  const spendRaw = d['Estimated Annual Spend (EUR)'] ?? d.annualSpendEur ?? 0;
  const annualSpendEur = parseMoney(spendRaw);
  const requesterEmail = String(d['Requester Email'] ?? d.requesterEmail ?? '').trim();
  const rowNumber = Number.isInteger(Number(d.row_number)) && Number(d.row_number) >= 2 ? Number(d.row_number) : null;
  const fromSheet = rowNumber !== null;

  const cleanedQuery = rawQuery.replace(/\s+/g, ' ').trim();
  const isValid = cleanedQuery.length >= 2 && cleanedQuery.length <= 160;
  const validationError = isValid
    ? null
    : 'Vendor identifier or legal name must be between 2 and 160 characters.';

  output.push({
    json: {
      query: cleanedQuery,
      defaultCountry: rawCountry,
      annualSpendEur,
      requesterEmail: requesterEmail || 'unspecified',
      fromSheet,
      row_number: rowNumber,
      submittedAt: new Date().toISOString(),
      isValid,
      validationError,
    },
  });
}
return output;

const HIGH_VALUE_THRESHOLD_EUR = 50000;
const inputItems = $input.all();
const results = [];

// Build query-keyed lookup from validated inputs so batch runs never misalign when invalid rows were filtered out
const metaByQuery = new Map();
let defaultMeta = { annualSpendEur: 0, requesterEmail: 'unspecified', defaultCountry: '', fromSheet: false, row_number: null, submittedAt: new Date().toISOString() };
try {
  const metaNodes = $('Normalize & Validate Vendor Input').all();
  for (const m of metaNodes) {
    const q = String(m.json?.query || '').trim().toLowerCase();
    if (q) metaByQuery.set(q, m.json);
  }
  if (metaNodes.length === 1 && metaNodes[0]?.json) {
    defaultMeta = metaNodes[0].json;
  }
} catch {
  // Fallback when tested standalone
}

for (const item of inputItems) {
  const r = item.json || {};
  const qKey = String(r.query || '').trim().toLowerCase();
  const reqMeta = metaByQuery.get(qKey) || defaultMeta;

  const flags = Array.isArray(r.kybRiskFlags) ? r.kybRiskFlags : [];
  const sanctions = r.sanctions || { status: 'UNAVAILABLE', totalMatches: 0, matches: [], sourcesChecked: [] };
  const kybStatus = String(r.kybStatus || 'NOT_FOUND');
  const annualSpendEur = Number(reqMeta.annualSpendEur || 0);

  const reasons = [];
  let riskScore = 0;

  if (sanctions.status === 'EXACT_MATCH') {
    riskScore += 100;
    reasons.push(`Sanctions EXACT MATCH (${sanctions.totalMatches} hit(s) on ${(sanctions.matches || []).map(m => m.source).join(', ')})`);
  } else if (sanctions.status === 'POTENTIAL_MATCH') {
    riskScore += 80;
    reasons.push(`Sanctions POTENTIAL MATCH (${sanctions.totalMatches} hit(s))`);
  } else if (sanctions.status === 'UNAVAILABLE') {
    riskScore += 40;
    reasons.push('Sanctions lists unavailable — manual compliance check required');
  }

  if (flags.includes('COMPANY_INACTIVE') || r.status === 'INACTIVE') {
    riskScore += 70;
    reasons.push('Company status is INACTIVE / dissolved');
  }
  if (flags.includes('VAT_INVALID') || r.vatValid === false) {
    riskScore += 60;
    reasons.push('EU VAT number reported INVALID by VIES');
  }
  if (flags.includes('INSOLVENCY_HISTORY')) {
    riskScore += 55;
    reasons.push('Insolvency history reported by registry');
  }
  if (flags.includes('VAT_UNVERIFIED')) {
    riskScore += 25;
    reasons.push('EU VIES temporarily unavailable (vatValid=null) — retry later, do not auto-reject');
  }
  if (!r.found || kybStatus === 'NOT_FOUND' || kybStatus === 'ERROR' || kybStatus === 'PARTIAL') {
    riskScore += 35;
    reasons.push(`Registry lookup returned ${kybStatus}`);
  }
  if (annualSpendEur >= HIGH_VALUE_THRESHOLD_EUR) {
    riskScore += 15;
    reasons.push(`High-value vendor (€${annualSpendEur.toLocaleString('en-US')}) requires Finance sign-off`);
  }

  riskScore = Math.min(100, riskScore);

  const isBlocked =
    sanctions.status === 'EXACT_MATCH' ||
    sanctions.status === 'POTENTIAL_MATCH' ||
    flags.includes('COMPANY_INACTIVE') ||
    flags.includes('VAT_INVALID') ||
    flags.includes('INSOLVENCY_HISTORY');

  const needsManualReview =
    !isBlocked &&
    (
      kybStatus !== 'VERIFIED_ACTIVE' ||
      sanctions.status !== 'CLEAR' ||
      flags.includes('VAT_UNVERIFIED') ||
      annualSpendEur >= HIGH_VALUE_THRESHOLD_EUR
    );

  const complianceDecision = isBlocked ? 'BLOCKED' : needsManualReview ? 'MANUAL_REVIEW' : 'APPROVED';
  if (complianceDecision === 'APPROVED' && reasons.length === 0) {
    reasons.push('Active entity verified via official registry, VAT valid or N/A, 0 OFAC/EU/UN sanctions hits');
  }

  const officersList = Array.isArray(r.officers)
    ? r.officers.slice(0, 5).map(o => `${o.name}${o.role ? ` (${o.role})` : ''}`).join('; ')
    : '';

  const sanctionsDetails = Array.isArray(sanctions.matches) && sanctions.matches.length > 0
    ? sanctions.matches.slice(0, 3).map(m => `[${m.source}] ${m.matchedName} (${m.matchType} ${m.score}, ${(m.programs || []).join('/')})`).join(' | ')
    : 'CLEAR';

  const vatStatusLabel = flags.includes('VAT_UNVERIFIED')
    ? 'UNVERIFIED'
    : (r.vatValid === null || r.vatValid === undefined ? 'N/A' : String(r.vatValid));

  const vendorKey = `${r.country || 'XX'}:${r.registrationNumber || r.vatNumber || r.query || 'unknown'}`;

  results.push({
    json: {
      vendorKey,
      checkedAt: r.checkedAt || new Date().toISOString(),
      query: r.query || reqMeta.query || '',
      legalName: r.legalName || r.query || 'Unknown',
      country: r.country || reqMeta.defaultCountry || '',
      registrationNumber: r.registrationNumber || '',
      vatNumber: r.vatNumber || '',
      vatValid: vatStatusLabel,
      leiCode: r.leiCode || '',
      companyStatus: r.status || 'UNKNOWN',
      address: r.address?.full || '',
      latestRevenueEur: r.latestRevenueEur ?? '',
      officersSummary: officersList,
      sanctionsStatus: sanctions.status || 'UNKNOWN',
      sanctionsDetails,
      kybRiskFlags: flags.join(', '),
      riskScore,
      complianceDecision,
      decisionReasons: reasons.join(' | '),
      annualSpendEur,
      requesterEmail: reqMeta.requesterEmail || 'unspecified',
      registryUrl: Array.isArray(r.registryUrls) ? (r.registryUrls[0] || '') : '',
      fromSheet: Boolean(reqMeta.fromSheet),
      row_number: reqMeta.row_number ?? null,
    },
  });
}

return results;
